'use strict';
const assert=require('assert'),Budget=require('./render-budget-core.js');
const atoms=Array.from({length:1122},(_,index)=>({atomId:`atom-${index}`,languageId:`language-${index%102}`,atomType:['STATE','TYPE','EFFECT'][index%3]}));
const safe=Budget.createPlan(atoms,{mode:'AUTO'}),repeat=Budget.createPlan(atoms,{mode:'SAFE'}),balanced=Budget.createPlan(atoms,{mode:'BALANCED'}),full=Budget.createPlan(atoms,{mode:'FULL'});
assert.strictEqual(safe.mode,'SAFE');
assert.strictEqual(safe.renderedAtomCount,384);
assert.strictEqual(safe.evidenceAtomCount,1122);
assert.strictEqual(safe.projectionHeldAtomCount,738);
assert.strictEqual(safe.languageCoverageCount,102);
assert.strictEqual(safe.selectionFingerprint,repeat.selectionFingerprint);
assert.strictEqual(balanced.renderedAtomCount,768);
assert.strictEqual(full.renderedAtomCount,1122);
assert.strictEqual(full.projectionHeldAtomCount,0);
assert.strictEqual(safe.truth.fullEvidenceRetained,true);
assert.strictEqual(safe.truth.omittedFromProjectionMeansAbsent,false);
assert.strictEqual(Budget.nextMode('SAFE'),'BALANCED');
assert.strictEqual(Budget.nextMode('BALANCED'),'FULL');
assert.strictEqual(Budget.nextMode('FULL'),'SAFE');
assert.strictEqual(atoms.length,1122);
console.log(JSON.stringify({ok:true,safeRendered:safe.renderedAtomCount,balancedRendered:balanced.renderedAtomCount,fullRendered:full.renderedAtomCount,languageCoverage:safe.languageCoverageCount,fingerprint:safe.selectionFingerprint,authority:safe.truth.authority},null,2));
